import{_ as e,c as p,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"9、【小畜】 乾下巽上","description":"周易闡真 - 9、【小畜】 乾下巽上","frontmatter":{"title":"9、【小畜】 乾下巽上","description":"周易闡真 - 9、【小畜】 乾下巽上"},"headers":[],"relativePath":"classics/chanzhen/010.md","filePath":"classics/chanzhen/010.md"}'),s={name:"classics/chanzhen/010.md"};function n(c,a,i,o,l,h){return t(),p("div",null,[...a[0]||(a[0]=[r('<blockquote><p>彖曰：小畜，柔得位而上下應之，曰小畜。健而巽，剛中而志行，乃亨。密雲不雨，尚往也；自我西郊，施未行也。</p></blockquote><h1 id="_9、【小畜】-乾下巽上" tabindex="-1">9、【小畜】 乾下巽上 <a class="header-anchor" href="#_9、【小畜】-乾下巽上" aria-label="Permalink to “9、【小畜】 乾下巽上”">​</a></h1><p>初九：復自道，何其咎，吉。</p><p>九二：牽復，吉。</p><p>九三:輿說輻，夫妻反目。</p><p>六四：有孚血，去惕出，無咎。</p><p>九五：有孚攣如，富以其鄰。</p><p>上九：既雨既處，尚德載婦。貞厲。月幾望，君子徵兇。</p><h2 id="孔易闡真-​" tabindex="-1">孔易闡真 ​ <a class="header-anchor" href="#孔易闡真-​" aria-label="Permalink to “孔易闡真 ​”">​</a></h2><p>大象：風行天上，小畜。君子以懿文德。</p><p>小畜者，養之小也。上巽風，下乾天，是風行天上也。風行天上，鼓動萬物，所養者廣；風行天上，只可清熱解燥，所養者少，小畜之象也。</p><p>君子有見於此，知儘性至命之學，乃竊陰陽，奪造化，轉生殺，扭樞機之大事，非得心傳者不能行。但大畜不能，亦須小畜，以是懿文德焉。懿者，美也，妝飾之謂。文者，威儀云為之文。威儀云為，雖非修德之大事，亦修德者之不可忽。如應物平順，執事恭敬，動作詳細，言語謹慎之類。藏其剛而用其柔，瞻前顧後，從容不迫，自無躁動失德之行，亦如風吹天上，燥氣悉化也。修德而至燥氣悉化，能小畜而即能大畜矣。</p><h2 id="悟元子註解-​" tabindex="-1">悟元子註解 ​ <a class="header-anchor" href="#悟元子註解-​" aria-label="Permalink to “悟元子註解 ​”">​</a></h2><p>畜，敕六反。說，音脫。幾，音機。</p><p>小畜者，小其養也。卦德上巽伏下乾健，健而巽行，巽伏其健，健不自用，故謂小畜。此以小養大之卦，承上師卦而來。師之道，借陽而退陰也。借陽退陰，貴乎先養其陽，能養其陽，則以小自居，滿而不盈，剛而不躁，有若無，實若虛，其心日下，其德日高，可以漸造於聖賢之域，此小畜所以有亨道也。但小畜雖亨，若大過於小，是柔道用事，剛道退位，志氣不振，懦弱無能，畜之小而亨之小，其行不遠，大道難成，猶如“密雲不雨，自我西郊”也。</p><p>陰氣結而為雲，陽氣通而為雨。只雲不雨，陰氣盛而陽氣弱，生機將息，我家之近者，尚無濟，他家之遠者，更何求?空空一小，入於寂滅之學，豈能還我乾元面目乎?此小畜之火候，不可不知也。</p><p>初九，剛而居卑，韜明養晦，抱道而處，不以外假而傷內真，是能復於自道也。能復自道，雖畜之小而得其養，剛氣日增，不但無咎，而且致吉。此大而自小之畜也。</p><p>九二，剛以柔用，敏而好學，不恥下問，結交有道君子，彼此資益，明善復初，是為牽復也。牽復之畜，外愈虛而內愈實，小而反得其吉。此大而知小之畜也。</p><p>九三，剛而自用，有己無人，乖和失中，終必敗剛，如輿說輻，而車不能行，又如夫妻反目，而家不能興。此大而不知小之畜也。</p><p>六四，以無能而處於有能之中，必有血傷之咎。然柔而得正，自信一己純陰，為害最大，而能借他家之陽，儆惕勉力，煉己持心，本有害者，可以脫去其害，本有咎者，可以歸於無咎。此小而知大之畜也。</p><p>九五，陽剛巽進於中正，真信在中，陰陽混合，金丹凝結，是有孚攣如矣。攣如之信，本固邦寧，命基堅牢，急須化其氣質之性，以歸真知之性，如富以鄰矣。此小而藏大之畜也。</p><p>上九，剛居柔位，在小畜之終，如既雨既處矣。雨所以濟亢旱，既雨則陽氣處而不亢，既處則陽氣和而雨無用。修道所以用陰者，特以制暴躁之假陽耳。假陽既息，真陽須進，小畜之終，正當大畜之時。若終於小而不能大，陰反傷陽，如尚德載婦，女子掌權，又如月幾於望，光明漸虧。修道君子，只知小而不知大，以之孤寂守靜，無作無為則可，以之儘性至命，行道致遠，適以招兇而已。此終於小而不知大之畜也。</p><p>觀於六爻之言，小畜原有亨道，是在人小之如何耳。小之當，則以小畜大而致吉；小之不當，則以小害大而招兇。學者可不先究其小中之火候乎?</p>',23)])])}const m=e(s,[["render",n]]);export{d as __pageData,m as default};
